'use client'

import { useCallback } from 'react'

import { usePortalTutorialPersistence } from '@apps/portal-tutorial/hooks/usePortalTutorialPersistence'
import { usePortalTutorialStore } from '@apps/portal-tutorial/stores/portal-tutorial.store'

export function usePortalTutorialDismiss() {
  const dismiss = usePortalTutorialStore((state) => state.dismiss)
  const { markDismissed } = usePortalTutorialPersistence()

  return useCallback(() => {
    markDismissed()
    dismiss()
  }, [dismiss, markDismissed])
}
