'use client'

import { useCallback, useEffect, useRef, useState } from 'react'

import { Button, Icon, IconComponent } from '@graftcode/design-system'

import { useLocalGatewayChrome } from '@/core/context/LocalGatewayChromeContext'
import { useElementTextOverflow } from '@/core/hooks/useElementTextOverflow'
import { GATEWAY_SELECTOR_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './GatewaySelector.module.scss'

const COPY_FEEDBACK_MS = 2000

interface GatewaySelectorProps {
  gatewayName: string
  loading: boolean
}

export function GatewaySelector({ gatewayName, loading }: GatewaySelectorProps) {
  const [copied, setCopied] = useState(false)
  const copyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const nameRef = useRef<HTMLSpanElement>(null)
  const localGatewayChrome = useLocalGatewayChrome()
  const displayText = gatewayName || 'Gateway'
  const isNameOverflowing = useElementTextOverflow(nameRef, [displayText])

  useEffect(() => {
    localGatewayChrome?.setGatewayNameTruncated(isNameOverflowing)
  }, [localGatewayChrome, isNameOverflowing])

  useEffect(
    () => () => {
      if (copyTimeoutRef.current) {
        clearTimeout(copyTimeoutRef.current)
      }
    },
    []
  )

  const handleCopy = useCallback(() => {
    if (loading || !gatewayName) return

    navigator.clipboard.writeText(gatewayName).then(() => {
      setCopied(true)

      if (copyTimeoutRef.current) {
        clearTimeout(copyTimeoutRef.current)
      }

      copyTimeoutRef.current = setTimeout(() => {
        setCopied(false)
        copyTimeoutRef.current = null
      }, COPY_FEEDBACK_MS)
    })
  }, [gatewayName, loading])

  if (loading) {
    return null
  }

  const wrapperClassName = localGatewayChrome ? `${styles.wrapper} ${styles.wrapperCompact}` : styles.wrapper

  return (
    <div data-testid={GATEWAY_SELECTOR_TEST_IDS.root} className={wrapperClassName}>
      <IconComponent icon={Icon.DSCodeGateway} className={styles.icon} />
      <span ref={nameRef} className={styles.name} title={displayText}>
        {displayText}
      </span>
      <div className={styles.copyActions}>
        <Button
          iconOnly
          icon={copied ? Icon.CopyFilled : Icon.CopyRegular}
          variant="ghost"
          size="s"
          className={styles.copyButton}
          onClick={handleCopy}
          aria-label={`Copy ${gatewayName}`}
          title={`Copy: ${gatewayName}`}
        />
      </div>
    </div>
  )
}
