'use client'

import { Header } from '@common/components/Header'
import { DEFAULT_PROFILE_ITEMS } from '@common/const'

import { GatewaySelector } from '@/core/components/GatewaySelector/GatewaySelector'
import { LocalGatewayChromeProvider } from '@/core/context/LocalGatewayChromeContext'
import { useIsLocalGatewayConfigurationMode } from '@/core/hooks/useIsLocalGatewayConfigurationMode'
import { LAYOUT_HEADER_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from '../../Layout.module.scss'

interface LayoutHeaderProps {
  isError: boolean
  isLoading: boolean
  gatewayName: string
  onProfileClick: (item: string) => void
  onMenuToggle: () => void
}

export function LayoutHeader({ isError, isLoading, gatewayName, onProfileClick, onMenuToggle }: LayoutHeaderProps) {
  const showLocalGatewayConfiguration = useIsLocalGatewayConfigurationMode()
  const showHostedGatewaySelector = !showLocalGatewayConfiguration && !isError && !isLoading

  const gatewaySelector = <GatewaySelector gatewayName={gatewayName} loading={isLoading} />

  if (isError && !showLocalGatewayConfiguration) {
    return (
      <header className="topbar">
        <Header
          profileItems={DEFAULT_PROFILE_ITEMS}
          searchDisabled
          notificationsDisabled
          onProfileClick={onProfileClick}
          onMenuToggle={onMenuToggle}
        />
      </header>
    )
  }

  if (showLocalGatewayConfiguration) {
    return (
      <header className={`topbar ${styles.localTopbar}`}>
        <div data-testid={LAYOUT_HEADER_TEST_IDS.root} className={styles.mobilePortalHeader}>
          <Header
            profileItems={DEFAULT_PROFILE_ITEMS}
            searchDisabled
            feedbackDisabled={!isError}
            notificationsDisabled
            onProfileClick={onProfileClick}
            onMenuToggle={onMenuToggle}
          />
        </div>
        <LocalGatewayChromeProvider>
          <div className={styles.localGatewaySelectorBar}>{gatewaySelector}</div>
        </LocalGatewayChromeProvider>
      </header>
    )
  }

  return (
    <header className="topbar">
      <div className={styles.mobilePortalHeader}>
        <Header
          profileItems={DEFAULT_PROFILE_ITEMS}
          searchDisabled
          feedbackDisabled
          notificationsDisabled
          onProfileClick={onProfileClick}
          onMenuToggle={onMenuToggle}
        />
      </div>

      {showHostedGatewaySelector ? <div className={styles.desktopGatewaySelector}>{gatewaySelector}</div> : null}
    </header>
  )
}
