import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class MailingService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Mailing.Facade.MailingService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {string} topic
   * @param {string} message
   * @param {number} rating
   * @returns {Promise<void>}
   */
  static async sendFeedbackEmail(token, topic, message, rating) {
    try {
      MailingService.type
        .invokeStaticMethod("SendFeedbackEmail", token, topic, message, rating)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} targetEmail
   * @param {string} invitationLink
   * @param {string} workspaceName
   * @param {string} projectName
   * @param {string} invitingUserName
   * @returns {Promise<void>}
   */
  static async sendProjectInvitationEmail(
    m2MToken,
    targetEmail,
    invitationLink,
    workspaceName,
    projectName,
    invitingUserName,
  ) {
    try {
      MailingService.type
        .invokeStaticMethod(
          "SendProjectInvitationEmail",
          m2MToken,
          targetEmail,
          invitationLink,
          workspaceName,
          projectName,
          invitingUserName,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} targetEmail
   * @param {string} invitationLink
   * @param {string} workspaceName
   * @param {string} invitingUserName
   * @returns {Promise<void>}
   */
  static async sendWorkspaceInvitationEmail(
    m2MToken,
    targetEmail,
    invitationLink,
    workspaceName,
    invitingUserName,
  ) {
    try {
      MailingService.type
        .invokeStaticMethod(
          "SendWorkspaceInvitationEmail",
          m2MToken,
          targetEmail,
          invitationLink,
          workspaceName,
          invitingUserName,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} targetEmail
   * @param {string} workspaceName
   * @param {string} projectName
   * @param {string} username
   * @returns {Promise<void>}
   */
  static async sendAcceptInvitationEmail(
    m2MToken,
    targetEmail,
    workspaceName,
    projectName,
    username,
  ) {
    try {
      MailingService.type
        .invokeStaticMethod(
          "SendAcceptInvitationEmail",
          m2MToken,
          targetEmail,
          workspaceName,
          projectName,
          username,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await MailingService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
