import { create } from 'zustand'
import { devtools } from 'zustand/middleware'
import { immer } from 'zustand/middleware/immer'

import { StoreDevtoolsName } from '@stores/store-names.const'

import { PORTAL_TUTORIAL_PHASE, PORTAL_TUTORIAL_STEPS } from '../portal-tutorial.const'

import { portalTutorialInitialState } from './portal-tutorial.slice'
import type { PortalTutorialStore } from './portal-tutorial.type'

export const usePortalTutorialStore = create<PortalTutorialStore>()(
  devtools(
    immer((set) => ({
      ...portalTutorialInitialState,

      openWelcome: () =>
        set((state) => {
          state.phase = PORTAL_TUTORIAL_PHASE.welcome
          state.currentStepIndex = 0
        }),

      startTour: () =>
        set((state) => {
          state.phase = PORTAL_TUTORIAL_PHASE.active
          state.currentStepIndex = 0
        }),

      nextStep: () =>
        set((state) => {
          if (state.currentStepIndex >= PORTAL_TUTORIAL_STEPS.length - 1) {
            state.phase = PORTAL_TUTORIAL_PHASE.completed
            return
          }

          state.currentStepIndex += 1
        }),

      previousStep: () =>
        set((state) => {
          if (state.currentStepIndex <= 0) return
          state.currentStepIndex -= 1
        }),

      dismiss: () =>
        set((state) => {
          state.phase = PORTAL_TUTORIAL_PHASE.idle
          state.currentStepIndex = 0
        }),

      complete: () =>
        set((state) => {
          state.phase = PORTAL_TUTORIAL_PHASE.completed
        }),

      reset: () =>
        set((state) => {
          state.phase = PORTAL_TUTORIAL_PHASE.idle
          state.currentStepIndex = 0
        }),
    })),
    {
      name: StoreDevtoolsName.PortalTutorial,
      enabled: process.env.NODE_ENV === 'development',
    }
  )
)
