'use client'

import { useTranslations } from 'next-intl'

import { Button } from '@graftcode/design-system'

import { PORTAL_TUTORIAL_TEST_IDS } from '@apps/portal-tutorial/portal-tutorial-test-ids.const'
import { usePortalTutorialStore } from '@apps/portal-tutorial/stores/portal-tutorial.store'

import { usePortalTutorialDismiss } from '../../hooks'

import styles from '../../PortalTutorial.module.scss'

export function PortalTutorialWelcome() {
  const t = useTranslations('portalTutorial')
  const startTour = usePortalTutorialStore((state) => state.startTour)
  const handleDismiss = usePortalTutorialDismiss()

  return (
    <div className={styles.welcome}>
      <div
        className={styles.welcomeCard}
        role="dialog"
        aria-modal="true"
        aria-labelledby="portal-tutorial-welcome-title"
        data-testid={PORTAL_TUTORIAL_TEST_IDS.welcome}
      >
        <div className={styles.welcomeHeader}>
          <h2 id="portal-tutorial-welcome-title" className={styles.welcomeTitle}>
            {t('welcome.title')}
          </h2>
        </div>
        <p className={styles.welcomeBody}>{t('welcome.description')}</p>
        <div className={styles.welcomeFooter}>
          <Button
            variant="outlined"
            size="m"
            text={t('welcome.maybeLater')}
            data-testid={PORTAL_TUTORIAL_TEST_IDS.maybeLater}
            onClick={handleDismiss}
          />
          <Button variant="primary" size="m" text={t('welcome.letsGo')} onClick={startTour} />
        </div>
      </div>
    </div>
  )
}
