'use client'

import { useEffect } from 'react'

import { usePortalTutorialPersistence } from '@apps/portal-tutorial/hooks/usePortalTutorialPersistence'
import { PORTAL_TUTORIAL_PHASE } from '@apps/portal-tutorial/portal-tutorial.const'
import { usePortalTutorialStore } from '@apps/portal-tutorial/stores/portal-tutorial.store'

export function usePortalTutorialLifecycle(autoStart: boolean, isDesktop: boolean) {
  const phase = usePortalTutorialStore((state) => state.phase)
  const openWelcome = usePortalTutorialStore((state) => state.openWelcome)
  const reset = usePortalTutorialStore((state) => state.reset)
  const { shouldAutoStart, markCompleted } = usePortalTutorialPersistence()

  useEffect(() => {
    if (!autoStart || !isDesktop || !shouldAutoStart) return
    openWelcome()
  }, [autoStart, isDesktop, openWelcome, shouldAutoStart])

  useEffect(() => {
    if (phase !== PORTAL_TUTORIAL_PHASE.completed) return
    markCompleted()
    reset()
  }, [markCompleted, phase, reset])
}
