import { ANALYTICS_GOOGLE_TAG_IDS } from '../analytics.const'

export interface GtmConfig {
  gtmId: string
  auth?: string
  preview?: string
  googleAdsId: string
}

type GtmWindow = Window & {
  dataLayer?: unknown[]
  gtag?: (...args: unknown[]) => void
}

function ensureGtagShim(gtmWindow: GtmWindow) {
  gtmWindow.dataLayer = gtmWindow.dataLayer || []
  gtmWindow.gtag =
    gtmWindow.gtag ||
    function gtag(...args: unknown[]) {
      gtmWindow.dataLayer!.push(args)
    }
}

export function getGtmConfig(): GtmConfig {
  const envGoogleAdsId = process.env.NEXT_PUBLIC_ANALYTICS_GOOGLE_ADS_ID?.trim()

  return {
    gtmId: process.env.NEXT_PUBLIC_ANALYTICS_GTM_ID!,
    auth: process.env.NEXT_PUBLIC_ANALYTICS_GTM_AUTH!,
    preview: process.env.NEXT_PUBLIC_ANALYTICS_GTM_PREVIEW!,
    googleAdsId: envGoogleAdsId || ANALYTICS_GOOGLE_TAG_IDS.defaultGoogleAdsConversionId,
  }
}

/** Registers Google Ads tag config on the same dataLayer / gtag shim used by GTM. */
export function pushGoogleAdsGtagConfig(googleAdsId: string) {
  if (typeof window === 'undefined' || !googleAdsId) return

  const gtmWindow = window as GtmWindow
  ensureGtagShim(gtmWindow)
  gtmWindow.gtag!('config', googleAdsId)
}

export function pushGtmConsentDataLayer(
  mode: 'default' | 'update',
  consentPayload: Record<string, 'granted' | 'denied'>
) {
  if (typeof window === 'undefined') return

  const gtmWindow = window as GtmWindow
  gtmWindow.dataLayer = gtmWindow.dataLayer || []
  gtmWindow.dataLayer.push(['consent', mode, consentPayload])
}
