'use client'

import { createPortal } from 'react-dom'

import { useBreakpoint } from '@common/hooks/useBreakpoints'

import { isPortalTutorialVisiblePhase, PORTAL_TUTORIAL_PHASE } from '@apps/portal-tutorial/portal-tutorial.const'
import { PORTAL_TUTORIAL_TEST_IDS } from '@apps/portal-tutorial/portal-tutorial-test-ids.const'
import { usePortalTutorialStore } from '@apps/portal-tutorial/stores/portal-tutorial.store'

import { PortalTutorialStepView, PortalTutorialWelcome } from './components'
import { usePortalTutorialLifecycle } from './hooks'

import styles from './PortalTutorial.module.scss'

type PortalTutorialProps = {
  autoStart?: boolean
}

export function PortalTutorial({ autoStart = false }: PortalTutorialProps) {
  const { isDesktop } = useBreakpoint()
  const phase = usePortalTutorialStore((state) => state.phase)

  usePortalTutorialLifecycle(autoStart, isDesktop)

  const isVisible = isPortalTutorialVisiblePhase(phase)

  if (!isDesktop || !isVisible || typeof document === 'undefined') {
    return null
  }

  return createPortal(
    <div className={styles.root} role="presentation" data-testid={PORTAL_TUTORIAL_TEST_IDS.root}>
      {phase === PORTAL_TUTORIAL_PHASE.welcome ? <PortalTutorialWelcome /> : <PortalTutorialStepView />}
    </div>,
    document.body
  )
}
