'use client'

import { useTranslations } from 'next-intl'

import { Button, Icon } from '@graftcode/design-system'

import { PORTAL_TUTORIAL_LAYOUT, PORTAL_TUTORIAL_STEPS } from '@apps/portal-tutorial/portal-tutorial.const'
import { PORTAL_TUTORIAL_TEST_IDS } from '@apps/portal-tutorial/portal-tutorial-test-ids.const'

import { usePortalTutorialStepView } from '../../hooks'
import { PortalTutorialOverlay } from '../../PortalTutorialOverlay'

import styles from '../../PortalTutorial.module.scss'

export function PortalTutorialStepView() {
  const t = useTranslations('portalTutorial')
  const {
    currentStep,
    currentStepIndex,
    isLastStep,
    targetRect,
    targetElement,
    isPositioned,
    floatingStyles,
    pointerSide,
    arrowData,
    setArrowElement,
    setFloatingElement,
    handleDismiss,
    previousStep,
    handleFinish,
  } = usePortalTutorialStepView()

  if (!currentStep) {
    return null
  }

  return (
    <>
      <PortalTutorialOverlay targetRect={targetRect} showHighlight />
      <div
        ref={setFloatingElement}
        className={styles.popover}
        style={{
          ...floatingStyles,
          visibility: targetElement && isPositioned ? 'visible' : 'hidden',
        }}
        role="dialog"
        aria-modal="true"
        data-testid={PORTAL_TUTORIAL_TEST_IDS.step}
      >
        <div
          ref={setArrowElement}
          className={styles.pointer}
          style={{
            left: arrowData?.x != null ? `${arrowData.x}px` : undefined,
            top: arrowData?.y != null ? `${arrowData.y}px` : undefined,
            [PORTAL_TUTORIAL_LAYOUT.pointerStaticSide[pointerSide]]: `-${PORTAL_TUTORIAL_LAYOUT.pointerWidth}px`,
            transform: `rotate(${PORTAL_TUTORIAL_LAYOUT.pointerRotation[pointerSide]}deg)`,
          }}
          aria-hidden
        >
          <div className={styles.pointerShape} />
        </div>
        <div className={styles.popoverCard}>
          <div className={styles.popoverHeader}>
            <h2 className={styles.popoverTitle}>{t(`steps.${currentStep}.title`)}</h2>
            <Button
              className={styles.closeButton}
              variant="ghost"
              size="m"
              iconOnly
              icon={Icon.DismissRegular}
              aria-label={t('actions.close')}
              onClick={handleDismiss}
            />
          </div>
          <p className={styles.popoverBody}>
            {t.rich(`steps.${currentStep}.description`, {
              strong: (chunks) => <strong>{chunks}</strong>,
            })}
          </p>
          <div className={styles.footer}>
            <Button
              variant="outlined"
              size="m"
              text={t('actions.back')}
              disabled={currentStepIndex === 0}
              onClick={previousStep}
            />
            <span className={styles.progress}>
              {t('progress', {
                current: currentStepIndex + 1,
                total: PORTAL_TUTORIAL_STEPS.length,
              })}
            </span>
            <Button
              variant="primary"
              size="m"
              text={isLastStep ? t('actions.finish') : t('actions.next')}
              onClick={handleFinish}
            />
          </div>
        </div>
      </div>
    </>
  )
}
