import type { MenuItem, MenuSeparator } from '@graftcode/design-system'
import { Icon } from '@graftcode/design-system'

import { DEFAULT_HELP_ITEMS, HELP_ITEM_ID } from '../help-menu.const'

export function buildPortalHelpItems(portalTourLabel: string): (MenuItem | MenuSeparator)[] {
  return [
    {
      type: 'item',
      active: true,
      groups: [],
      icon: Icon.FastForwardRegular,
      label: portalTourLabel,
      id: HELP_ITEM_ID.PORTAL_TOUR,
      size: 'xs',
    },
    {
      id: 'help-sep-portal-tour',
      type: 'separator',
    },
    ...DEFAULT_HELP_ITEMS,
  ]
}
