'use client'

import type { PropsWithChildren } from 'react'
import { useState } from 'react'

import { VisionMobileMenu } from '@common/components/MobileMenu/variants/VisionMobileMenu'

import { useLayoutStore } from '@stores/layout/layout.store'

import { VisionSidebar } from '@/core/components/Sidebar/Sidebar'
import { useLibraries } from '@/core/hooks/useLibraries'
import { useRegisterVisionUrl } from '@/core/hooks/useRegisterVisionUrl'
import { useVisionLibraryTree } from '@/core/hooks/useVisionLibraryTree'
import { selectPathString, useNavigationStore } from '@/core/stores'
import { LAYOUT_TEST_IDS } from '@/core/vision-test-ids.const'

import { LayoutHeader, LayoutMainContent } from './components'
import { useLayoutActions } from './hooks'
import { VISION_MENU_GROUPS } from './layout.const'

import '@styles/layout/layout.scss'

/** Vision app layout: sidebar, header, main content, mobile menu. */
export function LayoutClient({ children }: PropsWithChildren) {
  const { isVisionLocal } = useLayoutStore()
  const { gatewayDisplayName, isLoading, isError, hasNoModules, refetch } = useLibraries()
  useRegisterVisionUrl()
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)

  const pathString = useNavigationStore(selectPathString)
  const treeItems = useVisionLibraryTree()

  const {
    handleSignUpClick,
    handleRefresh,
    handleCreateGateway,
    handleMenuToggle,
    handleMobileMenuClose,
    handleProfileClick,
    handleNavigationClick,
    handleTreeItemClick,
    handleTreeItemToggle,
  } = useLayoutActions({ setMobileMenuOpen, refetch })

  return (
    <div
      data-testid={LAYOUT_TEST_IDS.root}
      className={`app-layout ${isError ? 'is-error' : ''} ${hasNoModules ? 'is-empty' : ''}`}
    >
      <aside className="sidebar">
        <VisionSidebar />
      </aside>

      <div className="main-content">
        <LayoutHeader
          isError={isError}
          isLoading={isLoading}
          gatewayName={gatewayDisplayName}
          onProfileClick={handleProfileClick}
          onMenuToggle={handleMenuToggle}
        />

        <LayoutMainContent
          isError={isError}
          isLoading={isLoading}
          isVisionLocal={isVisionLocal}
          pathString={pathString}
          onRefetchGateway={refetch}
          onRefresh={handleRefresh}
          onCreateGateway={handleCreateGateway}
          onSignUpClick={handleSignUpClick}
        >
          {children}
        </LayoutMainContent>
      </div>

      <VisionMobileMenu
        isOpen={mobileMenuOpen}
        onClose={handleMobileMenuClose}
        menuGroups={VISION_MENU_GROUPS}
        onProfileClick={handleProfileClick}
        onNavigationClick={handleNavigationClick}
        treeItems={treeItems}
        activeItemId={pathString || undefined}
        onTreeItemClick={handleTreeItemClick}
        onTreeItemToggle={handleTreeItemToggle}
        isLoading={isLoading}
        isError={isError}
      />
    </div>
  )
}
