'use client'

import { useCallback, useEffect, useState } from 'react'

import { arrow, autoUpdate, flip, offset, shift, useFloating } from '@floating-ui/react-dom'

import { PORTAL_TUTORIAL_LAYOUT, PORTAL_TUTORIAL_STEPS } from '@common/apps/portal-tutorial/portal-tutorial.const'

import { usePortalTutorialTargetElement } from '@apps/portal-tutorial/hooks/usePortalTutorialTargetElement'
import { usePortalTutorialTargetRect } from '@apps/portal-tutorial/hooks/usePortalTutorialTargetRect'
import type { PortalTutorialStepId } from '@apps/portal-tutorial/portal-tutorial.const'
import { getPortalTutorialDomTarget } from '@apps/portal-tutorial/portal-tutorial.utils'
import { usePortalTutorialStore } from '@apps/portal-tutorial/stores/portal-tutorial.store'

import { usePortalTutorialDismiss } from './usePortalTutorialDismiss'

export function usePortalTutorialStepView() {
  const { currentStepIndex, nextStep, previousStep, complete } = usePortalTutorialStore()
  const handleDismiss = usePortalTutorialDismiss()

  const [arrowElement, setArrowElement] = useState<HTMLDivElement | null>(null)
  const [floatingElement, setFloatingElement] = useState<HTMLDivElement | null>(null)

  const currentStep: PortalTutorialStepId | null = PORTAL_TUTORIAL_STEPS[currentStepIndex] ?? null
  const domTarget = currentStep ? getPortalTutorialDomTarget(currentStep) : null
  const targetRect = usePortalTutorialTargetRect(domTarget, true)
  const { element: targetElement, status: targetStatus } = usePortalTutorialTargetElement(domTarget, true)

  const { floatingStyles, placement, middlewareData, isPositioned } = useFloating<HTMLElement>({
    placement: 'right',
    strategy: 'fixed',
    elements: { reference: targetElement, floating: floatingElement },
    middleware: [
      offset(PORTAL_TUTORIAL_LAYOUT.popoverOffset),
      flip({ padding: PORTAL_TUTORIAL_LAYOUT.viewportPadding }),
      shift({ padding: PORTAL_TUTORIAL_LAYOUT.viewportPadding }),
      arrow({ element: arrowElement, padding: PORTAL_TUTORIAL_LAYOUT.viewportPadding }),
    ],
    whileElementsMounted: autoUpdate,
  })

  const pointerSide = placement.split('-')[0] as keyof typeof PORTAL_TUTORIAL_LAYOUT.pointerStaticSide
  const isLastStep = currentStepIndex === PORTAL_TUTORIAL_STEPS.length - 1

  useEffect(() => {
    if (targetStatus !== 'missing') return

    if (isLastStep) {
      complete()
      return
    }

    nextStep()
  }, [complete, isLastStep, nextStep, targetStatus])

  const handleFinish = useCallback(() => {
    if (isLastStep) {
      complete()
      return
    }

    nextStep()
  }, [complete, isLastStep, nextStep])

  return {
    currentStep,
    currentStepIndex,
    isLastStep,
    targetRect,
    targetElement,
    floatingStyles,
    isPositioned,
    pointerSide,
    arrowData: middlewareData.arrow,
    setArrowElement,
    setFloatingElement,
    handleDismiss,
    previousStep,
    handleFinish,
  }
}
